function structurePage(){const urls={branch:@js(route('hris.configuration.branches.store',['organization'=>$organization->slug])),department:@js(route('hris.configuration.departments.store',['organization'=>$organization->slug])),position:@js(route('hris.configuration.positions.store',['organization'=>$organization->slug]))};const labels={branch:{add:@js(__('hris.configuration.add_branch')),edit:@js(__('hris.configuration.edit_branch'))},department:{add:@js(__('hris.configuration.add_department')),edit:@js(__('hris.configuration.edit_department'))},position:{add:@js(__('hris.configuration.add_position')),edit:@js(__('hris.configuration.edit_position'))}};const blank=k=>({mode:'create',kind:k,action:urls[k],name:'',code:'',address:'',parent_id:''});return{tab:'branches',modal:false,form:blank('branch'),openCreate(k){this.form=blank(k);this.modal=true},openEdit(d){this.form={...blank(d.kind),...d,mode:'edit'};this.modal=true},modalTitle(){return this.form.mode==='edit'?labels[this.form.kind].edit:labels[this.form.kind].add}}}
</script>@endonce
